const key = (value: string) => normalize(value).replace(/ /g, "");

/** Merge the supplement into the base prompts: new answers are skipped if they collide with any accepted form. */
export function mergeDeepDiveExtras(prompts: readonly DeepPrompt[]): DeepPrompt[] {
  return prompts.map((prompt) => {
    const extra = deepDiveExtras[prompt.id];
    if (!extra) return prompt;
    const answers: DeepAnswer[] = prompt.answers.map((a) => ({ ...a, aliases: [...(a.aliases ?? [])] }));
    const taken = new Set(answers.flatMap((a) => [a.answer, ...(a.aliases ?? [])].map(key)));
    for (const [target, aliases] of Object.entries(extra.alias ?? {})) {
      const found = answers.find((a) => key(a.answer) === key(target));
      if (!found) continue;
      for (const alias of aliases) {
        if (!taken.has(key(alias))) { found.aliases!.push(alias); taken.add(key(alias)); }
      }
    }
    for (const [answer, tier, aliases = []] of extra.add ?? []) {
      if (taken.has(key(answer))) continue;
      const fresh = aliases.filter((alias) => !taken.has(key(alias)));
      answers.push({ answer, tier, aliases: fresh });
      [answer, ...fresh].forEach((form) => taken.add(key(form)));
    }
    return { ...prompt, answers };
  });
}

export const deepDivePromptsExpanded: DeepPrompt[] = mergeDeepDiveExtras(deepDivePrompts);
